#include <bits/stdc++.h>
typedef long long ll;
using namespace std;

int main() {
	// your code goes here
int t;
cin>>t;
while(t--)
{
    int n;
    cin>>n;
    int m=3*n;
    vector<ll>a(m);
    for(int i=0;i<m;i++)
    {
        cin>>a[i];
    }
    sort(a.rbegin(),a.rend());
    vector<ll>p(m+1,0);
    for(int i=0;i<m;i++)
    {
        p[i+1]=p[i]+a[i];
    }
    auto val=[&](int A,int B)
    {
        int last=3*n-2*A-B;
        return 2LL*p[A]+p[A+2*B]+3LL*p[last];
    };
    ll ans=0;
    for(int A=0;A<=n;A++)
    {
        int low=0;
        int high=n-A;
        while(low<high)
        {
            int B=(low+high+1)/2;
            int b=B-1;
           // ll left=a[A+2*B]+a[A+2*b+1];
           // int pos=3*n-2*A-b-1;
           // ll right=3LL*a[pos];
        
             // if(left>=right)
               //   low=B;
           // else
                //  high=B-1;
                int k=A+2*(B-1);
                int pos=3*n-2*A-B;
                ll diff=a[k]+a[k+1]-3LL*a[pos];
                if(diff>=0) low=B;
                else high=B-1;
        }
    int z=low;
    ans=max(ans,val(A,z));
    }
    cout<<ans<<endl;
}
}
